            "def": "CREATE OR REPLACE FUNCTION public.build_text_analysis_result(p_job_id uuid)\\n RETURNS uuid\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\nAS $function$\\ndeclare\\n  v_result_id uuid;\\n  v_result jsonb;\\n  v_warnings jsonb := '[]'::jsonb;\\n  v_result_status text;\\n  v_job_status text;\\n  v_total int;\\n  v_done int;\\n  v_partial int;\\n  v_failed int;\\nbegin\\n  select\\n    status,\\n    coalesce(total_items, 0),\\n    coalesce(done_items, 0),\\n    coalesce(partial_items, 0),\\n    coalesce(failed_items, 0)\\n  into v_job_status, v_total, v_done, v_partial, v_failed\\n  from lexeme_processing_jobs\\n  where id = p_job_id;\\n\\n  if v_job_status is null then\\n    raise exception 'Job not found: %', p_job_id;\\n  end if;\\n\\n  if v_total = 0 then\\n    v_result_status := 'building';\\n  elsif v_done + v_partial + v_failed >= v_total then\\n    if v_failed = v_total then\\n      v_result_status := 'failed';\\n    elsif v_failed > 0 or v_partial > 0 then\\n      v_result_status := 'partial_ready';\\n    else\\n      v_result_status := 'ready';\\n    end if;\\n  elsif v_done + v_partial + v_failed > 0 then\\n    v_result_status := 'partial_ready';\\n  else\\n    v_result_status := 'building';\\n  end if;\\n\\n  with item_rows as (\\n    select\\n      i.*,\\n\\n      fe.status as form_status,\\n      fe.quality as form_quality,\\n      fe.canonical_form,\\n      fe.form_type,\\n      fe.grammatical_features,\\n      fe.accepted_variants,\\n\\n      coalesce(lse.semantic_unit_id, ese.semantic_unit_id) as semantic_unit_id,\\n      coalesce(lse.semantic_confidence, ese.semantic_confidence) as semantic_enrichment_confidence,\\n      coalesce(lse.review_status, ese.review_status) as semantic_review_status,\\n      su.canonical_form as canonical_semantic_form,\\n      su.normalized_form as normalized_semantic_form,\\n      su.semantic_type,\\n      su.confidence as semantic_unit_confidence,\\n      su.trusted as semantic_unit_trusted,\\n\\n      coalesce(\\n        jsonb_agg(\\n          jsonb_build_object(\\n            'source', sc.source,\\n            'status', sc.status,\\n            'quality', sc.quality,\\n            'found', sc.found,\\n            'registered_entry', coalesce((sc.evidence->>'registered_entry')::boolean, false),\\n            'whole_unit_match', coalesce((sc.evidence->>'whole_unit_match')::boolean, false),\\n            'component_match', coalesce((sc.evidence->>'component_match')::boolean, false),\\n            'usage_match', coalesce((sc.evidence->>'usage_match')::boolean, false),\\n            'evidence_label', sc.evidence->>'evidence_label',\\n            'original_quality', sc.evidence->>'original_quality'\\n          )\\n          order by\\n            case sc.quality\\n              when 'strong' then 1\\n              when 'medium' then 2\\n              when 'weak' then 3\\n              when 'not_found' then 4\\n              when 'error' then 5\\n              else 6\\n            end,\\n            sc.source\\n        ) filter (where sc.id is not null),\\n        '[]'::jsonb\\n      ) as sources_summary,\\n\\n      max(\\n        case sc.quality\\n          when 'strong' then 5\\n          when 'medium' then 4\\n          when 'weak' then 3\\n          when 'not_found' then 1\\n          when 'error' then 0\\n          else 0\\n        end\\n      ) as best_quality_rank,\\n\\n      count(*) filter (where sc.found = true) as sources_found_count,\\n      count(*) filter (where sc.quality = 'strong') as strong_sources_count,\\n      count(*) filter (where sc.quality = 'medium') as medium_sources_count,\\n      count(*) filter (where sc.quality = 'weak') as weak_sources_count,\\n\\n      coalesce(\\n        jsonb_agg(sc.source order by sc.source)\\n          filter (where sc.found = true and sc.quality in ('strong', 'medium')),\\n        '[]'::jsonb\\n      ) as authoritative_sources,\\n\\n      bool_or(coalesce((sc.evidence->>'registered_entry')::boolean, false)) as has_registered_entry,\\n      bool_or(coalesce((sc.evidence->>'whole_unit_match')::boolean, false)) as has_whole_unit_match,\\n      bool_or(coalesce((sc.evidence->>'component_match')::boolean, false)) as has_component_match,\\n      bool_or(coalesce(sc.found, false)) as any_source_found\\n\\n    from lexeme_processing_items i\\n    left join lexeme_source_checks sc on sc.item_id = i.id\\n    left join lexeme_form_enrichment fe on fe.item_id = i.id\\n    left join lexeme_semantic_enrichment lse on lse.lexeme_id = i.lexeme_id\\n    left join expression_semantic_enrichment ese on ese.expression_id = i.expression_id\\n    left join canonical_semantic_units su on su.id = coalesce(lse.semantic_unit_id, ese.semantic_unit_id)\\n    where i.job_id = p_job_id\\n    group by\\n      i.id,\\n      fe.status,\\n      fe.quality,\\n      fe.canonical_form,\\n      fe.form_type,\\n      fe.grammatical_features,\\n      fe.accepted_variants,\\n      lse.semantic_unit_id,\\n      lse.semantic_confidence,\\n      lse.review_status,\\n      ese.semantic_unit_id,\\n      ese.semantic_confidence,\\n      ese.review_status,\\n      su.canonical_form,\\n      su.normalized_form,\\n      su.semantic_type,\\n      su.confidence,\\n      su.trusted\\n  ),\\n\\n  item_enriched as (\\n    select\\n      ir.*,\\n\\n      case ir.best_quality_rank\\n        when 5 then 'strong'\\n        when 4 then 'medium'\\n        when 3 then 'weak'\\n        when 1 then 'not_found'\\n        else 'unknown'\\n      end as best_quality,\\n\\n      (\\n        select sc2.source\\n        from lexeme_source_checks sc2\\n        where sc2.item_id = ir.id\\n        order by\\n          case sc2.quality\\n            when 'strong' then 1\\n            when 'medium' then 2\\n            when 'weak' then 3\\n            when 'not_found' then 4\\n            when 'error' then 5\\n            else 6\\n          end,\\n          sc2.source\\n        limit 1\\n      ) as best_source,\\n\\n      case\\n        when ir.strong_sources_count >= 2 then 'high'\\n        when ir.strong_sources_count >= 1 and ir.medium_sources_count >= 1 then 'high'\\n        when ir.strong_sources_count = 1 then 'medium'\\n        when ir.medium_sources_count >= 2 then 'medium'\\n        when ir.medium_sources_count = 1 or ir.weak_sources_count > 0 then 'low'\\n        else 'unverified'\\n      end as verification_confidence,\\n\\n      case\\n        when ir.has_registered_entry = true then true\\n        when ir.has_whole_unit_match = true and ir.best_quality_rank >= 4 then true\\n        when ir.pos = 'expression' and ir.has_whole_unit_match = true then true\\n        else false\\n      end as recommended_for_learning\\n\\n    from item_rows ir\\n  )\\n\\n  select jsonb_build_object(\\n    'job_id', j.id,\\n    'job_status', j.status,\\n    'result_status', v_result_status,\\n    'total_items', j.total_items,\\n    'done_items', j.done_items,\\n    'partial_items', j.partial_items,\\n    'failed_items', j.failed_items,\\n    'progress',\\n      case\\n        when coalesce(j.total_items, 0) = 0 then 0\\n        else round(\\n          ((coalesce(j.done_items, 0) + coalesce(j.partial_items, 0) + coalesce(j.failed_items, 0))::numeric\\n          / j.total_items::numeric) * 100,\\n          1\\n        )\\n      end,\\n    'items',\\n      coalesce(\\n        jsonb_agg(\\n          jsonb_build_object(\\n            'item_id', ie.id,\\n            'raw_input', ie.raw_input,\\n            'surface_form', ie.surface_form,\\n            'normalized_lemma', ie.normalized_lemma,\\n            'pos', ie.pos,\\n            'match_type', ie.match_type,\\n            'status', ie.status,\\n            'lexeme_id', ie.lexeme_id,\\n            'expression_id', ie.expression_id,\\n\\n            'semantic_unit_id', ie.semantic_unit_id,\\n            'canonical_semantic_form', ie.canonical_semantic_form,\\n            'normalized_semantic_form', ie.normalized_semantic_form,\\n            'semantic_type', ie.semantic_type,\\n            'semantic_unit_confidence', ie.semantic_unit_confidence,\\n            'semantic_unit_trusted', coalesce(ie.semantic_unit_trusted, false),\\n            'semantic_review_status', ie.semantic_review_status,\\n            'semantic_enrichment_confidence', ie.semantic_enrichment_confidence,\\n\\n            'best_quality', ie.best_quality,\\n            'best_source', ie.best_source,\\n            'verification_confidence', ie.verification_confidence,\\n\\n            'sources_found_count', coalesce(ie.sources_found_count, 0),\\n            'strong_sources_count', coalesce(ie.strong_sources_count, 0),\\n            'medium_sources_count', coalesce(ie.medium_sources_count, 0),\\n            'weak_sources_count', coalesce(ie.weak_sources_count, 0),\\n            'authoritative_sources', ie.authoritative_sources,\\n\\n            'registered_entry', coalesce(ie.has_registered_entry, false),\\n            'whole_unit_match', coalesce(ie.has_whole_unit_match, false),\\n            'component_match', coalesce(ie.has_component_match, false),\\n            'any_source_found', coalesce(ie.any_source_found, false),\\n            'recommended_for_learning', coalesce(ie.recommended_for_learning, false),\\n\\n            'form_status', ie.form_status,\\n            'form_quality', ie.form_quality,\\n            'canonical_form', ie.canonical_form,\\n            'form_type', ie.form_type,\\n            'grammatical_features', coalesce(ie.grammatical_features, '{}'::jsonb),\\n            'accepted_variants', coalesce(ie.accepted_variants, '[]'::jsonb),\\n\\n            'sources_summary', ie.sources_summary\\n          )\\n          order by ie.created_at\\n        ) filter (where ie.id is not null),\\n        '[]'::jsonb\\n      )\\n  )\\n  into v_result\\n  from lexeme_processing_jobs j\\n  left join item_enriched ie on ie.job_id = j.id\\n  where j.id = p_job_id\\n  group by j.id;\\n\\n  insert into text_analysis_results (\\n    job_id,\\n    status,\\n    result_json,\\n    warnings,\\n    updated_at\\n  )\\n  values (\\n    p_job_id,\\n    v_result_status,\\n    v_result,\\n    v_warnings,\\n    now()\\n  )\\n  on conflict (job_id)\\n  do update set\\n    status = excluded.status,\\n    result_json = excluded.result_json,\\n    warnings = excluded.warnings,\\n    updated_at = now()\\n  returning id into v_result_id;\\n\\n  return v_result_id;\\nend;\\n$function$\\n",
