            "def": "CREATE OR REPLACE FUNCTION public.create_empty_text_analysis_job(p_text text, p_user_id text DEFAULT NULL::text, p_ingestion_version text DEFAULT 'ts_expression_aware_ingestion_v1'::text)\\n RETURNS uuid\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\nAS $function$\\ndeclare\\n  v_job_id uuid;\\nbegin\\n  if p_text is null or length(trim(p_text)) = 0 then\\n    raise exception 'Text is required';\\n  end if;\\n\\n  insert into lexeme_processing_jobs (\\n    user_id,\\n    input_type,\\n    input_text,\\n    status,\\n    total_items,\\n    done_items,\\n    partial_items,\\n    failed_items,\\n    skipped_items,\\n    summary,\\n    created_at,\\n    updated_at\\n  )\\n  values (\\n    p_user_id,\\n    'text',\\n    p_text,\\n    'pending',\\n    0,\\n    0,\\n    0,\\n    0,\\n    0,\\n    jsonb_build_object(\\n      'ingestion_version', p_ingestion_version,\\n      'created_by', 'analyze_text_edge_function'\\n    ),\\n    now(),\\n    now()\\n  )\\n  returning id into v_job_id;\\n\\n  return v_job_id;\\nend;\\n$function$\\n",
